function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 10000) return 'nums needs 2 to 10000 values.';
  const n = nums.length;
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Every value must be between 1 and nums.length.';
  const count = new Array(n + 1).fill(0);
  for (const v of nums) count[v]++;
  let twice = 0, absent = 0;
  for (let v = 1; v <= n; v++) {
    if (count[v] === 2) twice++;
    else if (count[v] === 0) absent++;
    else if (count[v] !== 1) return 'No value may appear more than twice.';
  }
  if (twice !== 1 || absent !== 1) return 'Exactly one value must repeat and exactly one must be missing.';
  return null;
}

