function findErrorNums(nums) {
  const n = nums.length;
  const count = new Array(n + 1).fill(0);

  for (const num of nums) {
    count[num]++;
  }

  let duplicate = -1;
  let missing = -1;
  for (let value = 1; value <= n; value++) {
    if (count[value] === 2) {
      duplicate = value;
    } else if (count[value] === 0) {
      missing = value;
    }
  }
  return [duplicate, missing];
}

