function findErrorNums(nums) {
  const n = nums.length;
  const distinct = [...new Set(nums)];
  const total = nums.reduce((a, b) => a + b, 0);
  const distinctTotal = distinct.reduce((a, b) => a + b, 0);
  return [total - distinctTotal, n * (n + 1) / 2 - distinctTotal];
