function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 7);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  const lost = Math.floor(rand() * n);
  let copied = Math.floor(rand() * (n - 1));
  if (copied >= lost) copied++;
  nums[lost] = nums[copied];
  return [nums];
}
